const orig = $('When Called').first().json;
const impact = (orig.impact || '').trim();
const REAL_TIERS = ['Niski','Średni','Wysoki','Krytycznie ważne'];
const override = (orig.model_override != null && String(orig.model_override).trim() !== '') ? String(orig.model_override).trim() : null;

let row = null;
try { const r = $input.first().json; if (r && r.litellm_model) row = r; } catch (e) {}

let routing_default_used = false;
let routing_row_missing = false;
if (override) {
  row = { litellm_model: override, temperature: null, max_tokens: 4000, nudge: null, price_in_usd_per_1k: 0, price_out_usd_per_1k: 0, impact: '__override__' };
} else if (!row) {
  row = { litellm_model: 'haxe-sonnet-4-6-direct', temperature: 0.7, max_tokens: 4000, nudge: null,
          price_in_usd_per_1k: 0.003, price_out_usd_per_1k: 0.015, impact: '__fallback__' };
  if (REAL_TIERS.includes(impact)) routing_default_used = true;
  routing_row_missing = true;
} else if (row.impact === '__default__' && REAL_TIERS.includes(impact)) {
  routing_default_used = true;
}

const nudge = row.nudge ? (row.nudge + '\n\n---\n\n') : '';
const prompt = nudge + (orig.prompt || '');
const temperature = (row.temperature != null && row.temperature !== '') ? Number(row.temperature) : null;

// Multimodal (ADR-036 Block 5): content is ALWAYS an array (one schema, not two). Image refs
// (ClickUp URLs from read-input) are appended as image_url parts; LiteLLM fetches them. No images
// -> a single text part, semantically identical to a bare string through LiteLLM.
let imgs = [];
try { imgs = JSON.parse(orig.image_blocks_json || '[]'); } catch (e) { imgs = []; }
if (!Array.isArray(imgs)) imgs = [];
const content = [{ type: 'text', text: prompt }].concat(
  imgs.filter(b => b && b.ref).map(b => ({ type: 'image_url', image_url: { url: b.ref } }))
);
const messages = [{ role: 'user', content }];

return [{ json: {
  litellm_model: row.litellm_model,
  temperature,
  max_tokens: Number(row.max_tokens),
  price_in_usd_per_1k: Number(row.price_in_usd_per_1k || 0),
  price_out_usd_per_1k: Number(row.price_out_usd_per_1k || 0),
  prompt,
  messages,
  image_count: imgs.length,
  impact,
  task_type: orig.task_type || '',
  clickup_task_id: orig.clickup_task_id || '',
  triggered_by: orig.triggered_by || 'explicit_command',
  invocation_type: orig.invocation_type || 'explicit',
  caller_user_id: orig.caller_user_id || '',
  process_type: orig.process_type || '',
  routing_default_used,
  routing_row_missing
} }];

const routing = $('Resolve Routing').first().json;

// Pick whichever LLM branch produced a real completion. On primary failure
// (Call LiteLLM onError=continueErrorOutput) the Fallback to Opus node ran instead.
let okCall = null, okFb = null;
try { okCall = $('Call LiteLLM').first().json; } catch (e) {}
try { okFb = $('Fallback to Opus').first().json; } catch (e) {}
const hasBody = (x) => x && x.body && x.body.choices;
let resp = {}, fell_back = false;
if (hasBody(okCall)) { resp = okCall; fell_back = false; }
else if (hasBody(okFb)) { resp = okFb; fell_back = true; }
else { resp = (okCall && okCall.body) ? okCall : (okFb || {}); }

const body = resp.body || {};
const headers = resp.headers || {};
const usage = body.usage || {};
const input_tokens = (usage.prompt_tokens != null) ? usage.prompt_tokens : null;
const output_tokens = (usage.completion_tokens != null) ? usage.completion_tokens : null;
let completion = '';
try { completion = body.choices[0].message.content || ''; } catch (e) {}
const ch = headers['x-litellm-response-cost'];
const usd_cost = (ch != null && ch !== '') ? Number(ch) : null;

const fbAlias = 'haxe-opus-4-8-direct';
const alias = fell_back ? fbAlias : (routing.litellm_model || '');
const model_used = (body.model && body.model.trim()) ? body.model.trim() : alias;
const provider = alias.includes('gemini') ? 'litellm/vertex' : 'litellm/anthropic-direct';

// On fallback the model differs from the routed one. LiteLLM's response-cost header
// is authoritative; these price columns are only a dormant backup. Keep them roughly
// correct for the common direct fallback case (Opus 4.8).
const price_in = fell_back ? 0.015 : routing.price_in_usd_per_1k;
const price_out = fell_back ? 0.075 : routing.price_out_usd_per_1k;

return [{ json: {
  completion,
  model_used,
  provider,
  input_tokens, output_tokens, usd_cost,
  price_in_usd_per_1k: price_in,
  price_out_usd_per_1k: price_out,
  routing_default_used: !!routing.routing_default_used,
  routing_row_missing: !!routing.routing_row_missing,
  fell_back_to_opus: fell_back,
  impact: routing.impact,
  task_type: routing.task_type,
  clickup_task_id: routing.clickup_task_id,
  triggered_by: routing.triggered_by,
  invocation_type: routing.invocation_type,
  caller_user_id: routing.caller_user_id,
  process_type: routing.process_type
} }];
